#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the HTML output
    std::stringstream htmlStream;

    // Write the markdown text to the string stream
    htmlStream << markdown;

    // Return the HTML string
    return htmlStream.str();
}

int main() {
    std::string markdownText = "This is a markdown text.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

